[Form]
public class METVendSiteSettingsSetup extends FormRun
{
    SysLookupMultiSelectCtrl lookupPOSubmissionMode;
    SysLookupMultiSelectCtrl lookupPOSubmissionChangeMode;
    SysLookupMultiSelectCtrl lookupPOSendCampaignMethod;
    
}

        /// <summary>
    /// The form init method. 
    /// </summary>
    public void init()
    {   
        super();

        this.initPOSubmissionLookup();
        this.initPOSubmissionChangeLookup();
        this.initPOSendCampaignMethodLookup();
    }

    /// <summary>
    /// Initilises the multi select lookup for given control.
    /// </summary>
    private void initPOSubmissionLookup()
    {
        Query query = new Query();
        QueryBuildDataSource queryBuildDataSource;
        QueryBuildRange queryBuildRange;
        SysDictEnum sysDictEnum = new SysDictEnum(enumNum(METVendSitePOSetup));

        queryBuildDataSource = query.addDataSource(tableNum(METMultiSelectBaseEnumTable));
        queryBuildDataSource.fields().dynamic(NoYes::Yes);
        queryBuildDataSource.fields().addField(fieldNum(METMultiSelectBaseEnumTable, EnumText));
        
        queryBuildRange = queryBuildDataSource.addRange(fieldNum(METMultiSelectBaseEnumTable, EnumName));
        queryBuildRange.value(sysDictEnum.name());

        lookupPOSubmissionMode = SysLookupMultiSelectCtrl::constructWithQuery(element, POSubmissionMode, query);
    }

    /// <summary>
    /// Initilises the multi select lookup for given control.
    /// </summary>
    private void initPOSubmissionChangeLookup()
    {
        Query query = new Query();
        QueryBuildDataSource queryBuildDataSource;
        QueryBuildRange queryBuildRange;
        SysDictEnum sysDictEnum = new SysDictEnum(enumNum(METVendSitePOSetup));

        queryBuildDataSource = query.addDataSource(tableNum(METMultiSelectBaseEnumTable));
        queryBuildDataSource.fields().dynamic(NoYes::Yes);
        queryBuildDataSource.fields().addField(fieldNum(METMultiSelectBaseEnumTable, EnumText));
        
        queryBuildRange = queryBuildDataSource.addRange(fieldNum(METMultiSelectBaseEnumTable, EnumName));
        queryBuildRange.value(sysDictEnum.name());
        
        lookupPOSubmissionChangeMode = SysLookupMultiSelectCtrl::constructWithQuery(element, POSubmissionChangeMode, query);
    }

    /// <summary>
    /// Initilises the multi select lookup for given control.
    /// </summary>
    private void initPOSendCampaignMethodLookup()
    {
        Query query = new Query();
        QueryBuildDataSource queryBuildDataSource;
        QueryBuildRange queryBuildRange;
        SysDictEnum sysDictEnum = new SysDictEnum(enumNum(METVendSitePOSetup));

        queryBuildDataSource = query.addDataSource(tableNum(METMultiSelectBaseEnumTable));
        queryBuildDataSource.fields().dynamic(NoYes::Yes);
        queryBuildDataSource.fields().addField(fieldNum(METMultiSelectBaseEnumTable, EnumText));
        
        queryBuildRange = queryBuildDataSource.addRange(fieldNum(METMultiSelectBaseEnumTable, EnumName));
        queryBuildRange.value(sysDictEnum.name());
    }

/// <summary>
/// Updates the multi select lookup control values.
/// </summary>
private void updateLookupValues()
{
    POSubmissionMode.text(METVendSiteSettingsSetup.POSubMode);
    POSubmissionChangeMode.text(METVendSiteSettingsSetup.POChngSubMode);
}

    /// <summary>
    /// Set form controls
    /// </summary>
    private void updateControlValues()
    {   
        if (METVendSiteSettingsSetup.POSubMode == METConstants::Email || METVendSiteSettingsSetup.POSubMode == '')
        {
            METVendSiteSettingsSetup.FASetting = NoYes::No;
        }

        if (METVendSiteSettingsSetup.ETradeSetting == NoYes::No)
        {
            METVendSiteSettingsSetup.ASNSetting = NoYes::No;
            METVendSiteSettingsSetup.EInvoiceSetting = NoYes::No;
        }

        if (METVendSiteSettingsSetup.ASNSetting == NoYes::No)
        {
            METVendSiteSettingsSetup.ExpressReceiptSetting = NoYes::No;            
        }

        if (METVendSiteSettingsSetup.ETradeSetting == NoYes::No)
        {
            METVendSiteSettingsSetup.POASetting = NoYes::No;
        }
        
    }

    /// <summary>
    /// The active method of the form datasource.
    /// </summary>
    /// <returns>Integer value.</returns>
    public int active()
    {
        int ret;

        ret = super();
        element.updateLookupValues();
        
        return ret;
    }

/// <summary>
/// Marks the values seleted on multi select lookup.
/// </summary>
private void updateLookupControl()
{   
    this.updateLookupControlValue(POSubmissionMode, lookupPOSubmissionMode, METVendSiteSettingsSetup.POSubMode);
    this.updateLookupControlValue(POSubmissionChangeMode, lookupPOSubmissionChangeMode, METVendSiteSettingsSetup.POChngSubMode);
}

        /// <summary>
        /// Marks the values seleted on multi select lookup.
        /// </summary>
        /// <param name = "_formStringControl">The form string control</param>
        /// <param name = "_multiSelectLookup">The multi select lookup object</param>
        /// <param name = "_value">The value from the form datasource</param>
        private void updateLookupControlValue(FormStringControl _formStringControl, SysLookupMultiSelectCtrl _multiSelectLookup, str _value)
        {
            _formStringControl.text(_value);
            container recIds, names;
            RecId recId;
            List list = new List(Types::String);
            ListIterator iterator;
            SysDictEnum sysDictEnum = new SysDictEnum(enumNum(METVendSitePOSetup));

            list = Global::strSplit(_value, METConstants::Semicolon);
            iterator = new ListIterator(list);

            while(iterator.more())
            {
                recId = METMultiSelectBaseEnumTable::findByEnumValue(sysDictEnum.name(), iterator.value()).RecId;
                recIds += recId;
                names += iterator.value();
                iterator.next();
            }

            _multiSelectLookup.set([recIds, names]);
        }

/// <summary>
/// The execute query method of the form datasource.
/// </summary>
public void executeQuery()
{
    super();
    this.updateLookupControl();
}

        /// <summary>
        /// The validate write method of the form datasource.
        /// </summary>
        /// <returns>True or false</returns>
        public boolean validateWrite()
        {
            boolean ret;
        
            ret = super();

            if (ret)
            {
                if (METVendSiteSettingsSetup.POEmailAddresses == '' && (METVendSiteSettingsSetup.POSubMode != METConstants::EDI && METVendSiteSettingsSetup.POSubMode != ''))
                {   
                    throw error("@MET:METPOEmailAddressError");
                }

                if (!METVendSiteSettingsSetup.DefaultItemCoverWH
                    && METVendSiteSettingsSetup.DefaultPlannedOrderType == METVendSiteSetupDefaultPlannedOrderType::Transfer)
                {
                    throw error("@MET:METDefaulMainWHError");
                }
            }
        
            return ret;
        }

        /// <summary>
        /// The init value method of the form datasource.
        /// </summary>
        public void initValue()
        {
            super();

            // Set empty containers for new record.
            container recIds, names;
            lookupPOSubmissionMode.set([recIds, names]);
            lookupPOSubmissionChangeMode.set([recIds, names]);

            MetVendSiteSettingsSetup metVendSiteSettingsSetupLocal;
            VendTable vendTable = element.args().record();

            if (!metVendSiteSettingsSetup.RecId && vendTable)
            {
                select firstonly metVendSiteSettingsSetupLocal
                    order by Level desc
                where metVendSiteSettingsSetupLocal.AssignedVendorAccount == vendTable.AccountNum;

                if (metVendSiteSettingsSetupLocal)
                {
                    buf2Buf(metVendSiteSettingsSetupLocal, metVendSiteSettingsSetup);
                }
            }
        }

