/// <summary>
/// Lookup method for invent location id 
/// </summary>
/// <param name = "_formControl">The form string control</param>
/// <param name = "_filterStr">The filter string</param>
public void lookup(FormControl _formControl, str _filterStr)
{
    if (METVendSiteSettingsSetup.AssignedSite)
    {
        InventLocation::lookupBySiteIdAllTypes(_formControl, METVendSiteSettingsSetup.AssignedSite);
    }
    else
    {
        super(_formControl, _filterStr);
    }
}

/// <summary>
/// The modified method of the datasource.
/// </summary>
public void modified()
{
    super();
    METVendSiteSettingsSetup.AssignedSite = InventLocation::find(METVendSiteSettingsSetup.AssignedWH).InventSiteId;
}

/// <summary>
/// behaviour if Planned order type, if Transfer order then Default warehouse is mandatory
/// </summary>
public void modified()
{
    super();
    METVendSiteSettingsSetup_ds.object(fieldNum(METVendSiteSettingsSetup, DefaultItemCoverWH)).mandatory(METVendSiteSettingsSetup.DefaultPlannedOrderType == METVendSiteSetupDefaultPlannedOrderType::Transfer);
}

